(function(){const v=LW.tiles,l="#1f2b45";function t(i){const T=i.some(b=>b[0]==="*");let g=0,e=2,y="";return i.forEach((b,d)=>{const x=b[0]==="*",k=b[0]==="#",C=x||k?b.slice(1):b,s=Math.round(C.replace(/[{}]/g,"").length*9.2+22);g&&g+s>320&&(g=0,e+=46);const r=`x="${g+2}" y="${e}" width="${s}" height="38" rx="10"`;y+=x?`<rect class="tp" data-id="w${d}" onclick="lnTap(this)" ${r}/>`:T?`<rect class="tpx" data-id="x${d}" onclick="lnTap(this)" ${r}/>`:`<rect ${r} fill="${k?"#fff1b8":"#fff"}" stroke="${l}" stroke-width="2.4"/>`;const w=C.replace(/\{([^}]+)\}/g,'<tspan style="fill:#e8453c">$1</tspan>');y+=`<text x="${g+2+s/2}" y="${e+25}" text-anchor="middle" class="ln-svgtxt" pointer-events="none">${w}</text>`,g+=s+8}),LW.svg(324,e+38+2,y,340)}const h=(i,p)=>`<div style="background:#fffdf3;border:2px solid #f1d48a;border-radius:14px;padding:12px 14px;text-align:left;line-height:1.65;font-size:16px;color:${l}">${i?`<div style="text-align:center;font-weight:800;font-size:17px;margin-bottom:4px">${i}</div>`:""}${p}</div>`,n=i=>i.replace(/ /g," "),c=i=>({order:i.map(n),ans:i.map(n).join(" ")}),a=h("Giờ ra chơi","Tùng! Tùng! Tùng! Tiếng trống ra chơi vừa vang lên, sân trường đã rộn ràng hẳn. Dưới gốc bàng, mấy bạn nữ chơi nhảy dây, bím tóc tung lên như những cánh bướm. Góc sân bên kia, các bạn nam say sưa đá cầu. Mấy bạn lớp một thì ngồi quanh bồn hoa, chụm đầu xem truyện tranh. Ai cũng vui vẻ, tươi tỉnh. Hết giờ ra chơi, cả trường lại vào lớp, sẵn sàng cho tiết học mới."),u=h("Chiếc ví đánh rơi","Trên đường đi học về, Nam nhặt được một chiếc ví. Trong ví có tiền và giấy tờ. Bạn Tuấn đi cùng bảo: “Hay mình lấy tiền mua kem ăn đi!” Nam lắc đầu: “Không được, người mất chắc đang lo lắm.” Nam mang chiếc ví đến đồn công an gần nhà. Hôm sau, một bác đến tận trường cảm ơn Nam. Tuấn đỏ mặt, nói nhỏ: “Tớ sai rồi. Lần sau tớ sẽ làm giống cậu.”"),o=h("Thỏ Nâu học bơi","Thỏ Nâu rất muốn học bơi nhưng lại sợ nước. Hôm đầu, Thỏ chỉ dám ngồi trên bờ. Vịt Bầu không cười bạn, chỉ dặn: “Cậu cứ tập từng chút một.” Ngày nào Thỏ cũng xuống nước, khi thì tập thở, khi thì tập đạp chân. Có hôm Thỏ bị sặc nước, mắt đỏ hoe, nhưng hôm sau vẫn đến. Cuối hè, Thỏ Nâu bơi được một vòng quanh hồ. Cả khu rừng vỗ tay khen ngợi."),m=h("Mưa xuân","Mưa xuân rơi nhè nhẹ<br>Như sợi chỉ mỏng manh<br>Cây bàng vừa thức giấc<br>Nhú lộc biếc trên cành.<br><br>Hàng cau đứng ngoài ngõ<br>Như những chú lính canh<br>Hạt mưa đậu trên lá<br>Long lanh như hạt cườm.<br><br>Bé ra sân đón mưa<br>Tay xoè như cánh én<br>Mưa xuân ơi, mưa xuân<br>Cho mầm non lớn lên.");LEARN.add({id:"hoc-tv3",grade:3,name:"Tiếng Việt 3",icon:"📖",who:"rabbit",color:"#12b26e",title:"Tiếng Việt lớp 3 — học cả năm",blurb:"Từ ngữ, câu, biện pháp so sánh, chính tả, đọc hiểu và viết: giảng ngắn, làm thử ngay, luyện 5 câu nhận sao."},[{id:"chinhta3",name:"Chính tả",en:"Spelling",icon:"✏️",color:"#ff6b6b",lessons:[{id:"tv3.ct-sx-chtr",title:"Viết s hay x, ch hay tr",emoji:"🌫️",min:5,who:"tiger",cards:[{t:"say",pose:"wave",text:"Chào em, Hổ Vằn đây! Lên lớp 3, em gặp nhiều từ khó hơn: <b>giọt sương</b> hay <b>giọt xương</b>? <b>chăn chiếu</b> hay <b>trăn chiếu</b>? Cùng luyện mắt tinh nhé!"},{t:"pic",svg:v([["🌫️","giọt <b>s</b>ương"],["🦴","khúc <b>x</b>ương"],["🐦","chim <b>s</b>ẻ"],["🪵","<b>x</b>ẻ gỗ"]]),cap:"Đổi <b>s</b> thành <b>x</b> là đổi nghĩa. Em phải nghĩ <b>nghĩa của từ</b> rồi mới viết."},{t:"say",text:"Mẹo thứ nhất: tên nhiều <b>con vật, cây cối</b> viết <b>s</b>: con sóc, con sâu, con sứa, cây sen, cây sả, cây sắn (vẫn có vài từ viết x như quả xoài)."},{t:"try",q:{text:'Điền <b>s</b> hay <b>x</b>: "Đàn chim …ẻ ríu rít trên cành." Gõ chữ cần điền.',input:!0,ans:"s",hint:"Đây là tên một loài chim nhỏ. Nhớ mẹo về tên con vật.",why:'<b>chim sẻ</b> là tên con vật, viết <b>s</b>. Còn "xẻ" là cưa, bổ ra (xẻ gỗ).'}},{t:"say",text:"Mẹo thứ hai: <b>từ láy</b> có hai tiếng thường cùng âm đầu: cùng <b>s</b> (sạch sẽ, sung sướng) hoặc cùng <b>x</b> (xinh xắn, xào xạc, xa xôi)."},{t:"tap",text:"Chạm vào các tiếng <b>viết sai</b> chính tả.",svg:t(["Vườn","nhà","bà","*xạch","sẽ,","hoa","nở","*sinh","xắn,","lá","cây","xào","xạc."]),need:2,done:'Sửa lại: xạch → <b>sạch</b> (sạch sẽ), sinh → <b>xinh</b> (xinh xắn). Còn "xào xạc" viết đúng: hai tiếng cùng x.'},{t:"say",text:"Với <b>ch/tr</b>: đồ dùng trong nhà hay viết <b>ch</b>: chăn, chiếu, chổi, chậu, chai. Và <b>tr</b> không đứng trước vần bắt đầu bằng <b>oa, oă, oe, uê</b>: chỉ có áo <b>ch</b>oàng, loắt <b>ch</b>oắt."},{t:"try",q:{text:"Từ nào viết <b>đúng</b> chính tả?",opts:["áo troàng","trăn chiếu","chăn chiếu","cái trổi"],ans:2,hint:"Nhớ mẹo: đồ dùng trong nhà hay viết ch; tr không đứng trước vần oa.",why:'Viết đúng: <b>chăn chiếu</b>, áo <b>ch</b>oàng, cái <b>ch</b>ổi. "trăn" là con trăn, không phải cái chăn đắp.'}},{t:"steps",title:"Cách chọn khi phân vân",items:[{text:"Bước 1: Nghĩ <b>nghĩa</b> của từ trong câu."},{text:'Bước 2: Ghép thử thành từ quen: "sương" trong sương mù, "xương" trong xương cá.'},{text:"Bước 3: Nếu là từ láy, hai tiếng thường cùng âm đầu: <b>tr</b>ong <b>tr</b>ẻo, <b>ch</b>ăm <b>ch</b>ỉ, <b>s</b>ạch <b>s</b>ẽ."},{text:"Bước 4: Vẫn chưa chắc thì hỏi thầy cô hoặc tra từ điển."}]},{t:"try",q:{text:'Điền <b>ch</b> hay <b>tr</b>: "Mặt …ời mọc ở đằng đông." Gõ chữ cần điền.',input:!0,ans:"tr",hint:'Từ này cùng âm đầu với "trăng" (ông trăng).',why:"<b>mặt trời</b>, bầu trời, chân trời đều viết <b>tr</b>."}},{t:"tip",text:"• Nghĩ <b>nghĩa</b> trước rồi mới chọn s/x, ch/tr.<br>• Tên nhiều con vật, cây cối viết <b>s</b>; đồ dùng trong nhà hay viết <b>ch</b>.<br>• Từ láy: hai tiếng thường <b>cùng âm đầu</b> (sạch sẽ, xinh xắn, chăm chỉ).<br>• <b>tr</b> không đứng trước vần oa, oă, oe, uê."}],practice:[{id:"tv3.ct-sx-chtr.1",text:'Điền <b>s</b> hay <b>x</b>: "Bé …ách cặp đi học."',opts:["s","x"],ans:1,why:"<b>xách</b> cặp: cầm quai mà mang đi, viết <b>x</b>."},{id:"tv3.ct-sx-chtr.2",text:"Từ nào viết <b>sai</b> chính tả?",opts:["sung sướng","xa xôi","xạch sẽ","xinh xắn"],ans:2,why:"Từ láy hai tiếng cùng âm đầu s: <b>sạch sẽ</b>. Các từ còn lại đều đúng."},{id:"tv3.ct-sx-chtr.3",text:'Điền <b>ch</b> hay <b>tr</b>: "Ông ngồi …ẻ lạt để buộc rau."',opts:["ch","tr"],ans:0,why:'<b>chẻ</b>: dùng dao bổ dọc ra (chẻ lạt, chẻ củi). Còn "trẻ" là trẻ em, còn nhỏ tuổi.'},{id:"tv3.ct-sx-chtr.4",text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Mẹ phơi trăn chiếu ngoài xân.","Mẹ phơi chăn triếu ngoài sân.","Mẹ phơi chăn chiếu ngoài xân.","Mẹ phơi chăn chiếu ngoài sân."],ans:3,why:"Viết đúng: <b>chăn chiếu</b> (đồ dùng trong nhà, viết ch) và ngoài <b>sân</b> (s)."},{id:"tv3.ct-sx-chtr.5",text:'Điền <b>s</b> hay <b>x</b> vào cả hai chỗ trống: "Lá cây …ào …ạc trong gió." Gõ chữ cần điền.',input:!0,ans:"x",why:"<b>xào xạc</b> là từ láy, hai tiếng cùng âm đầu <b>x</b>."}]},{id:"tv3.ct-dgir-ln",title:"Viết d, gi hay r; l hay n",emoji:"🦗",min:5,who:"bear",cards:[{t:"say",pose:"wave",text:"Chào em, Gấu Mít đây! Nhiều nơi đọc <b>d, gi, r</b> gần giống nhau, có nơi lẫn <b>l</b> với <b>n</b>. Đọc thì không sao, nhưng viết thì phải đúng!"},{t:"pic",svg:v([["🦗","con <b>d</b>ế"],["🌬️","cơn <b>gi</b>ó"],["🧺","cái <b>r</b>ổ"],["🐢","con <b>r</b>ùa"]]),cap:"dế, gió, rổ, rùa: đọc gần giống nhau mà viết khác nhau."},{t:"say",text:"Cách nhớ thứ nhất: nhớ theo <b>nhóm từ quen</b>. <b>gi</b>: gió, giấy, giày, giường, giặt. <b>r</b>: rau, rổ, rùa, rừng, ruộng. <b>d</b>: dao, dây, dép, dưa, dừa."},{t:"try",q:{text:'Điền <b>d</b>, <b>gi</b> hay <b>r</b>: "Mẹ …ặt quần áo cho cả nhà."',opts:["d","gi","r"],ans:1,hint:"Việc làm sạch quần áo bằng nước và xà phòng. Nó ở nhóm từ nào?",why:"<b>giặt</b> quần áo viết <b>gi</b>, cùng nhóm với giấy, giày, giường."}},{t:"say",text:"Cách nhớ thứ hai: <b>từ láy</b> có hai tiếng cùng âm đầu: <b>d</b>ịu <b>d</b>àng, <b>gi</b>òn <b>gi</b>ã, <b>r</b>ì <b>r</b>ào, <b>r</b>ộn <b>r</b>àng."},{t:"tap",text:"Chạm vào các tiếng <b>viết sai</b> chính tả.",svg:t(["Suối","chảy","*dóc","rách,","gió","thổi","*dì","rào,","hoa","lá","*gung","rinh."]),need:3,done:"Viết đúng: <b>róc rách, rì rào, rung rinh</b>. Đây là từ láy, hai tiếng cùng âm đầu <b>r</b>."},{t:"say",text:"Với <b>l/n</b>: chữ <b>n</b> hầu như không đứng trước vần bắt đầu bằng <b>oa, oe, uâ, uy</b>. Vì thế ta viết: cái <b>l</b>oa, <b>l</b>oè loẹt, <b>l</b>uật lệ, <b>l</b>uyện tập."},{t:"try",q:{text:'Điền <b>l</b> hay <b>n</b>: "Em chăm chỉ …uyện viết chữ đẹp." Gõ chữ cần điền.',input:!0,ans:"l",hint:"Nhìn vần đứng sau chỗ trống: uyên. Nhớ mẹo vừa học.",why:"<b>luyện</b>: vần uyên bắt đầu bằng u (âm đệm), nên viết <b>l</b>."}},{t:"steps",title:"Cách làm khi phân vân",items:[{text:"Bước 1: Đặt từ vào câu, nghĩ <b>nghĩa</b> của nó."},{text:"Bước 2: Tìm từ láy: hai tiếng thường cùng âm đầu (rì rào, lung linh, no nê)."},{text:"Bước 3: Nhớ nhóm từ quen: gió, giấy (gi); rau, rừng (r); dao, dây (d)."},{text:"Bước 4: Với l/n: vần bắt đầu bằng oa, oe, uâ, uy thì viết <b>l</b>."}]},{t:"try",q:{text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Lước suối trong veo, nấp nánh.","Nước suối trong veo, nấp lánh.","Nước suối trong veo, lấp lánh.","Lước suối trong veo, lấp lánh."],ans:2,hint:'Xét từng tiếng: "nước" uống, và từ láy "lấp lánh" (hai tiếng cùng âm đầu).',why:"Viết đúng: <b>nước</b> suối, <b>lấp lánh</b> (từ láy, hai tiếng cùng l)."}},{t:"tip",text:"• Nhớ nhóm từ quen: <b>gi</b> (gió, giấy, giường), <b>r</b> (rau, rổ, rừng), <b>d</b> (dao, dây, dép).<br>• Từ láy: hai tiếng thường <b>cùng âm đầu</b>: rì rào, dịu dàng, lung linh.<br>• Vần bắt đầu bằng oa, oe, uâ, uy → viết <b>l</b>: loa, luật, luyện."}],practice:[{id:"tv3.ct-dgir-ln.1",text:'Điền <b>d</b>, <b>gi</b> hay <b>r</b>: "Bà dặn em quét nhà cho sạch …ác."',opts:["d","gi","r"],ans:2,why:"<b>rác</b> viết <b>r</b>: quét rác, thùng rác."},{id:"tv3.ct-dgir-ln.2",text:"Từ nào viết <b>sai</b> chính tả?",opts:["dịu dàng","rộn ràng","giòn giã","dì rầm"],ans:3,why:'Từ láy hai tiếng cùng âm đầu r: <b>rì rầm</b>. "dì" là em gái của mẹ.'},{id:"tv3.ct-dgir-ln.3",text:'Điền <b>l</b> hay <b>n</b>: "Trời …ắng to, em đội mũ khi ra đường."',opts:["l","n"],ans:1,why:"<b>nắng</b> viết <b>n</b>: trời nắng, ánh nắng."},{id:"tv3.ct-dgir-ln.4",text:"Từ nào viết <b>đúng</b> chính tả?",opts:["cái loa","nuyện tập","noè loẹt","nuật lệ"],ans:0,why:"Vần bắt đầu bằng oa, oe, uâ, uy thì viết l: <b>cái loa</b>, luyện tập, loè loẹt, luật lệ."},{id:"tv3.ct-dgir-ln.5",text:'Điền <b>d</b>, <b>gi</b> hay <b>r</b>: "Bé nằm ngủ trên chiếc …ường nhỏ." Gõ chữ cần điền.',input:!0,ans:"gi",why:"<b>giường</b> ngủ viết <b>gi</b>, cùng nhóm với gió, giấy, giày."}]},{id:"tv3.ct-vankho",title:"Vần khó: oăc, oăt, uyu, ươu, iêu, yêu",emoji:"🦌",min:6,who:"frog",cards:[{t:"say",pose:"wave",text:"Chào em, Ếch Cốm đây! Có những vần ít gặp nên rất dễ viết sai: dấu <b>ngoặc</b>, đường <b>khúc khuỷu</b>, con <b>hươu</b>… Hôm nay mình làm quen từng vần nhé!"},{t:"pic",svg:v([["🦌","con h<b>ươu</b>"],["🪁","con d<b>iều</b>"],["❤️","<b>yêu</b> thương"],["( )","dấu ng<b>oặc</b>"]]),cap:"Bốn vần hôm nay: <b>ươu, iêu, yêu, oăc</b>."},{t:"say",text:"Vần <b>oăc, oăt</b> có chữ <b>ă</b> ở giữa: dấu ngoặc, ngoắc tay; nhọn hoắt, thoăn thoắt, loắt choắt. Đừng nhầm với <b>oac, oat</b> như khoác áo, hoạt động."},{t:"try",q:{text:'Chọn từ viết <b>đúng</b>: "Đôi chân bé chạy …"',opts:["thoan thoát","thoăn thoắt","thoăn thoát"],ans:1,hint:"Từ này có vần oăn và oăt, cả hai tiếng đều có chữ ă.",why:"<b>thoăn thoắt</b>: nhanh và liên tục. Hai tiếng đều có chữ <b>ă</b>."}},{t:"say",text:'Vần <b>uyu</b> rất hiếm: đường khúc <b>khuỷu</b>, <b>khuỷu</b> tay, ngã <b>khuỵu</b>. Vần <b>ươu</b>: con <b>hươu</b>, chim <b>khướu</b>, cái <b>bướu</b> lạc đà. Đừng viết thành "hưu".'},{t:"try",q:{text:'Chọn tiếng đúng: "Con … cao cổ ăn lá trên cây."',opts:["hưu","hươu","hiêu"],ans:1,hint:"Tên con vật này có vần ươu, giống chim khướu.",why:'<b>hươu</b> cao cổ: vần <b>ươu</b>. "hưu" là nghỉ hưu, không phải con vật.'}},{t:"say",text:"<b>iêu</b> hay <b>yêu</b>? Tiếng <b>không có âm đầu</b> thì viết <b>yêu</b>: yêu thương, yếu ớt. Tiếng <b>có âm đầu</b> thì viết <b>iêu</b>: con diều, chiếu, tiêu."},{t:"tap",text:"Chạm vào các tiếng <b>viết sai</b> chính tả.",svg:t(["Bé","rất","*iêu","đàn","*hưu","sao","trên","con","đường","khúc","*khỉu","lên","đồi."]),need:3,done:"Sửa lại: iêu → <b>yêu</b> (không có âm đầu), hưu → <b>hươu</b>, khỉu → <b>khuỷu</b> (khúc khuỷu)."},{t:"steps",title:"Bí kíp nhớ vần khó",items:[{text:"<b>oăc, oăt</b>: có chữ ă: ngoặc đơn, ngoắc tay, nhọn hoắt, thoăn thoắt."},{text:"<b>uyu</b>: chỉ vài từ: khúc khuỷu, khuỷu tay, khuỵu gối."},{text:"<b>ươu</b>: con hươu, chim khướu, cái bướu."},{text:"<b>yêu</b> khi không có âm đầu; <b>iêu</b> khi có âm đầu: yêu – diều."}]},{t:"try",q:{text:"Từ nào viết <b>đúng</b> chính tả?",opts:["dấu ngoạc đơn","yêu quý","con hưu","iêu thương"],ans:1,hint:"Kiểm tra từng từ với bí kíp: có cần chữ ă không? Có âm đầu không?",why:"<b>yêu quý</b> viết đúng. Sửa lại: dấu ngoặc đơn, con hươu, yêu thương."}},{t:"tip",text:"• <b>oăc, oăt</b> có chữ ă: ngoặc, thoắt, choắt.<br>• <b>uyu</b> rất hiếm: khuỷu, khuỵu.<br>• <b>ươu</b>: hươu, khướu, bướu.<br>• Không có âm đầu viết <b>yêu</b>, có âm đầu viết <b>iêu</b>."}],practice:[{id:"tv3.ct-vankho.1",text:"Tiếng nào có vần <b>uyu</b>?",opts:["khuya","khuỷu","khuyên","khoẻ"],ans:1,why:"<b>khuỷu</b> (khuỷu tay) có vần uyu. khuya: vần uya; khuyên: vần uyên; khoẻ: vần oe."},{id:"tv3.ct-vankho.2",text:'Chọn vần đúng: "Bé … bà nhất nhà."',opts:["yêu","iêu"],ans:0,why:"Tiếng không có âm đầu nên viết <b>yêu</b>."},{id:"tv3.ct-vankho.3",text:"Từ nào viết <b>sai</b> chính tả?",opts:["thoăn thoắt","nhọn hoắt","ngoặc đơn","loắt choát"],ans:3,why:"Viết đúng là <b>loắt choắt</b>: cả hai tiếng đều có vần oăt (có chữ ă)."},{id:"tv3.ct-vankho.4",text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Chú hưu non chạy thoăn thoắt.","Chú hươu non chạy thoan thoát.","Chú hươu non chạy thoăn thoắt.","Chú hưu non chạy thoăn thoát."],ans:2,why:"Viết đúng: chú <b>hươu</b> (vần ươu) chạy <b>thoăn thoắt</b> (có chữ ă)."},{id:"tv3.ct-vankho.5",text:"Trong các từ: <b>dấu ngoặc, khoác áo, nhọn hoắt, hoạt động, thoăn thoắt</b>, có mấy từ chứa vần <b>oăc</b> hoặc <b>oăt</b> (có chữ ă)? Gõ số.",input:!0,ans:"3",why:"Có 3 từ: dấu ng<b>oặc</b> (oăc), nhọn h<b>oắt</b> (oăt), tho<b>ăn</b> th<b>oắt</b> (oăt). Còn kh<b>oác</b> (oac), h<b>oạt</b> (oat) không có chữ ă."}]},{id:"tv3.ct-van-ng",title:"Vần ăn – ăng, ân – âng, ưt – ưc",emoji:"🌙",min:5,who:"cat",cards:[{t:"say",pose:"wave",text:"Chào em, Mèo Miu đây! <b>Cái khăn</b> hay <b>cái khăng</b>? <b>Nâng niu</b> hay <b>nân niu</b>? Chỉ khác chữ cuối <b>n – ng</b>, <b>t – c</b> thôi mà nghĩa khác hẳn!"},{t:"pic",svg:t(["kh{ăn}","tr{ăng}","s{ân}","t{ầng}","m{ứt}","m{ực}"]),cap:"khăn – trăng, sân – tầng, mứt – mực. Phần tô đỏ là vần. Nghe kĩ chữ cuối: <b>n</b> hay <b>ng</b>, <b>t</b> hay <b>c</b>."},{t:"say",text:'Mẹo đọc: tiếng có chữ cuối <b>n, t</b> thì đầu lưỡi chạm chân răng trên. Tiếng có <b>ng, c</b> thì đầu lưỡi không chạm, cuống lưỡi nâng lên. Em đọc chậm "khăn – khăng" thử xem!'},{t:"try",q:{text:'Chọn tiếng đúng: "Em quàng … đỏ đi học."',opts:["khăng","khăn"],ans:1,hint:'Đây là vật em đeo ở cổ. Cùng vần với "khăn mặt".',why:"<b>khăn</b> quàng đỏ, khăn mặt: vần <b>ăn</b>."}},{t:"say",text:"Cặp <b>ân/âng</b>: <b>sân</b> trường, <b>chân</b> tay, <b>ân</b> cần – <b>nâng</b> niu, <b>tầng</b> nhà, <b>vâng</b> lời. Cặp <b>ăn/ăng</b>: chăn bông, khăn mặt – măng tre, trăng rằm, hăng hái."},{t:"tap",text:"Chạm vào các tiếng có vần <b>âng</b>.",svg:t(["*vâng","lời","*nâng","niu","sân","trường","lên","*tầng","ba","chân","thành","ân","cần"]),need:3,done:"<b>vâng, nâng, tầng</b> có vần âng. Còn sân, chân, ân, cần có vần ân (không có g)."},{t:"say",text:"Cặp <b>ưt/ưc</b>: <b>mứt</b> tết, <b>nứt</b> nẻ, <b>đứt</b> dây – lọ <b>mực</b>, <b>sức</b> khoẻ, <b>thức</b> dậy, <b>rực</b> rỡ."},{t:"try",q:{text:'"Sáng nào em cũng th… dậy lúc sáu giờ." Tiếng còn thiếu có chữ cuối là <b>t</b> hay <b>c</b>? Gõ chữ đó.',input:!0,ans:"c",hint:"Đọc chậm từ đó: cuối tiếng, đầu lưỡi có chạm chân răng không?",why:"<b>thức</b> dậy: vần <b>ưc</b>, chữ cuối là <b>c</b>."}},{t:"steps",title:"Cách kiểm tra khi viết xong",items:[{text:"Bước 1: Đọc lại từng tiếng có chữ cuối n/ng, t/c."},{text:'Bước 2: Thử đổi: "khăn" thành "khăng" thì có còn đúng nghĩa không?'},{text:"Bước 3: Ghép với từ quen: khăn mặt, trăng rằm, nâng niu, vâng lời, mứt tết, lọ mực."}]},{t:"try",q:{text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Ông trăn tròn sáng trên sâng nhà.","Ông trăng tròn sáng trên sâng nhà.","Ông trăn tròn sáng trên sân nhà.","Ông trăng tròn sáng trên sân nhà."],ans:3,hint:'Xét hai tiếng: "trăng" rằm và "sân" trường.',why:"Viết đúng: ông <b>trăng</b> (vần ăng) và <b>sân</b> nhà (vần ân)."}},{t:"tip",text:"• Đọc chậm, nghe <b>chữ cuối</b>: n hay ng, t hay c.<br>• Thử đổi chữ cuối xem có còn đúng nghĩa không.<br>• Nhớ từ quen: khăn – trăng, sân – tầng, mứt – mực."}],practice:[{id:"tv3.ct-van-ng.1",text:'Chọn tiếng đúng: "Bé ngoan ngoãn, luôn … lời ông bà."',opts:["vân","vâng"],ans:1,why:"<b>vâng</b> lời: vần <b>âng</b>."},{id:"tv3.ct-van-ng.2",text:"Từ nào có vần <b>ưt</b>?",opts:["mứt dừa","lọ mực","sức khoẻ","rực rỡ"],ans:0,why:"<b>mứt</b> có vần ưt. Mực, sức, rực đều có vần ưc."},{id:"tv3.ct-van-ng.3",text:"Từ nào viết <b>sai</b> chính tả?",opts:["măng tre","khăn mặt","chăng bông","trăng rằm"],ans:2,why:'Cái chăn đắp viết <b>chăn</b> bông (vần ăn). "chăng" là chăng dây, chăng lưới.'},{id:"tv3.ct-van-ng.4",text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Mặt đất khô nức nẻ.","Mặt đấc khô nức nẻ.","Mặt đấc khô nứt nẻ.","Mặt đất khô nứt nẻ."],ans:3,why:"Viết đúng: mặt <b>đất</b> (vần ât), <b>nứt</b> nẻ (vần ưt)."},{id:"tv3.ct-van-ng.5",text:'"Cả lớp ân c… hỏi thăm bạn bị ốm." Tiếng còn thiếu có chữ cuối là <b>n</b> hay <b>ng</b>? Gõ chữ đó.',input:!0,ans:"n",why:"<b>ân cần</b>: cả hai tiếng đều có vần ân, chữ cuối là <b>n</b>."}]},{id:"tv3.ct-hoinga",title:"Dấu hỏi hay dấu ngã",emoji:"🎨",min:6,who:"panda",cards:[{t:"say",pose:"wave",text:"Chào em, Gấu Trúc Pu đây! <b>Vẽ</b> tranh hay <b>vẻ</b> tranh? <b>Nghỉ</b> ngơi hay <b>nghĩ</b> ngơi? Dấu hỏi và dấu ngã hay bị nhầm nhất. Pu có bí kíp đây!"},{t:"pic",svg:v([["🎨","v<b>ẽ</b> tranh"],["😊","vui v<b>ẻ</b>"],["🛏️","ngh<b>ỉ</b> ngơi"],["🤔","suy ngh<b>ĩ</b>"]]),cap:"vẽ, nghĩ: dấu <b>ngã</b>. vẻ, nghỉ: dấu <b>hỏi</b>. Cùng vần mà khác dấu là khác nghĩa."},{t:"try",q:{text:'Chọn tiếng đúng: "Em ngồi … tranh con mèo."',opts:["vẻ","vẽ"],ans:1,hint:"Việc dùng bút màu tạo ra bức tranh. Nhìn lại hình vừa rồi.",why:'<b>vẽ</b> tranh: dấu ngã. Còn "vẻ" (dấu hỏi) có trong vui vẻ, vẻ đẹp.'}},{t:"say",text:'Bí kíp với <b>từ láy</b>, nhớ câu: <b>"Huyền – ngã – nặng; hỏi – sắc – ngang"</b>. Tiếng kia có dấu huyền hoặc nặng thì tiếng này dấu <b>ngã</b>. Tiếng kia có dấu sắc hoặc không dấu thì tiếng này dấu <b>hỏi</b>.'},{t:"steps",title:"Thử bí kíp với 4 từ láy",items:[{text:'<b>rõ ràng</b>: "ràng" có dấu huyền → "rõ" dấu ngã.'},{text:'<b>đẹp đẽ</b>: "đẹp" có dấu nặng → "đẽ" dấu ngã.'},{text:'<b>vui vẻ</b>: "vui" không có dấu → "vẻ" dấu hỏi.'},{text:'<b>nhỏ nhắn</b>: "nhắn" có dấu sắc → "nhỏ" dấu hỏi.'}]},{t:"try",q:{text:"Từ láy nào viết <b>đúng</b>?",opts:["dể dàng","mát mẽ","sẵn sàng","vội vả"],ans:2,hint:"Nhìn dấu của tiếng kia: huyền, nặng đi với ngã; sắc, ngang đi với hỏi.",why:'"sàng" có dấu huyền nên <b>sẵn</b> dấu ngã: sẵn sàng. Sửa lại: dễ dàng, mát mẻ, vội vã.'}},{t:"tap",text:"Chạm vào các tiếng có <b>dấu ngã</b>.",svg:t(["Chị","*vẽ","bầu","trời","thật","*rõ","ràng.","Em","ngồi","nghỉ","và","*nghĩ","ngợi."]),need:3,done:'<b>vẽ, rõ, nghĩ</b> có dấu ngã. Còn "nghỉ" (nghỉ ngơi) có dấu hỏi.'},{t:"say",text:"Từ không phải từ láy thì nhớ theo <b>nghĩa</b>: <b>nghỉ</b> ngơi – suy <b>nghĩ</b>; dạy <b>bảo</b> – cơn <b>bão</b>; cái <b>cổ</b> – mâm <b>cỗ</b>. Bí kíp từ láy cũng có vài từ ngoại lệ, phân vân thì tra từ điển."},{t:"try",q:{text:'Chọn tiếng đúng: "Đêm qua có cơn … lớn, cây đổ nhiều."',opts:["bảo","bão"],ans:1,hint:"Gió rất to, mưa rất lớn gọi là gì?",why:'<b>cơn bão</b>: dấu ngã. Còn "bảo" (dấu hỏi) là dạy bảo, bảo ban.'}},{t:"try",q:{text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Bạn Nam học giỏi, tính tình vui vẽ.","Bạn Nam học giõi, tính tình vui vẻ.","Bạn Nam học giỏi, tính tình vui vẻ."],ans:2,hint:'Xét "vui v…": "vui" không dấu nên tiếng kia dấu gì?',why:"Viết đúng: học <b>giỏi</b>, vui <b>vẻ</b> (hai tiếng đều dấu hỏi)."}},{t:"tip",text:"• Từ láy: <b>huyền, nặng</b> đi với <b>ngã</b>; <b>sắc, không dấu</b> đi với <b>hỏi</b>.<br>• Ví dụ: rõ ràng, đẹp đẽ (ngã); vui vẻ, nhỏ nhắn (hỏi).<br>• Từ khác: nhớ theo nghĩa: nghỉ – nghĩ, bảo – bão, cổ – cỗ.<br>• Phân vân thì tra từ điển."}],practice:[{id:"tv3.ct-hoinga.1",text:'Chọn tiếng đúng: "Giờ ra chơi, cả lớp được … mười lăm phút."',opts:["nghĩ","nghỉ"],ans:1,why:'<b>nghỉ</b> (nghỉ ngơi, nghỉ giải lao): dấu hỏi. "nghĩ" là suy nghĩ.'},{id:"tv3.ct-hoinga.2",text:'Theo bí kíp "huyền – ngã – nặng", từ láy nào viết <b>đúng</b>?',opts:["mạnh mẻ","lặng lẽ","sạch sẻ","dể dàng"],ans:1,why:'"lặng" có dấu nặng nên <b>lẽ</b> dấu ngã: lặng lẽ. Sửa lại: mạnh mẽ, sạch sẽ, dễ dàng.'},{id:"tv3.ct-hoinga.3",text:"Từ nào viết <b>sai</b> chính tả?",opts:["vui vẻ","nhỏ nhắn","hớn hở","thơ thẫn"],ans:3,why:'"thơ" không có dấu nên tiếng kia dấu hỏi: <b>thơ thẩn</b>.'},{id:"tv3.ct-hoinga.4",text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Ngày Tết, bà bày mâm cỗ thật đẹp đẽ.","Ngày Tết, bà bày mâm cổ thật đẹp đẽ.","Ngày Tết, bà bày mâm cỗ thật đẹp đẻ.","Ngày Tết, bà bày mâm cổ thật đẹp đẻ."],ans:0,why:'<b>mâm cỗ</b>: dấu ngã (cái cổ mới là dấu hỏi). <b>đẹp đẽ</b>: "đẹp" dấu nặng nên đi với dấu ngã.'},{id:"tv3.ct-hoinga.5",text:'Câu "Chị vẽ tranh rõ đẹp, em vui vẻ ngồi xem." có mấy tiếng mang <b>dấu ngã</b>? Gõ số.',input:!0,ans:"2",why:'Có 2 tiếng mang dấu ngã: <b>vẽ, rõ</b>. Tiếng "vẻ" mang dấu hỏi.'}]},{id:"tv3.ct-viethoa",title:"Viết hoa tên người, tên địa lí",emoji:"🗺️",min:5,who:"eagle",cards:[{t:"say",pose:"wave",text:"Chào em, Đại Bàng Gió đây! Bay khắp đất nước, Gió gặp bao nhiêu cái tên đẹp: <b>Hà Nội, Huế, Cà Mau, sông Hồng</b>… Viết những tên này phải <b>viết hoa</b> cho đúng!"},{t:"steps",title:"Quy tắc 1: Tên người Việt Nam",items:[{text:"Viết hoa chữ cái đầu của <b>mỗi tiếng</b> trong tên."},{text:"Họ, tên đệm, tên: tiếng nào cũng viết hoa: <b>Nguyễn Thị Lan</b>, <b>Trần Quốc Toản</b>."}]},{t:"try",q:{text:'Bạn viết tên mình là "lê thị hoa". Bạn phải viết hoa những tiếng nào?',opts:['Chỉ tiếng "lê"','Tiếng "lê" và "hoa"',"Cả ba tiếng",'Chỉ tiếng "hoa"'],ans:2,hint:"Tên có 3 tiếng: họ, tên đệm, tên. Nhớ lại quy tắc 1.",why:"<b>Lê Thị Hoa</b>: viết hoa chữ cái đầu của cả 3 tiếng."}},{t:"say",text:"Quy tắc 2: Tên địa lí Việt Nam (tỉnh, thành phố, sông, núi, hồ…) cũng viết hoa <b>mỗi tiếng</b>: Hải Phòng, Đà Nẵng, Phú Quốc. Từ chung đứng trước như <b>sông, núi, hồ, tỉnh</b> thì <b>không</b> viết hoa: sông Hồng, núi Ba Vì."},{t:"tap",text:"Chạm vào các tiếng <b>cần viết hoa</b> mà bạn viết thường.",svg:t(["Nghỉ","hè,","em","về","*đà","*lạt","thăm","dì","*mai","và","ngắm","hồ","*xuân","*hương."]),need:5,done:'Viết đúng: Nghỉ hè, em về <b>Đà Lạt</b> thăm dì <b>Mai</b> và ngắm hồ <b>Xuân Hương</b>. Chữ "hồ" là từ chung nên viết thường.'},{t:"try",q:{text:'Câu "Nhà bà em ở gần sông hồng." cần sửa thế nào?',opts:['Viết hoa chữ "sông"','Viết hoa chữ "hồng"','Viết hoa cả "sông" và "hồng"',"Không cần sửa"],ans:1,hint:'"sông" là từ chung; "Hồng" là tên riêng của con sông.',why:'Viết hoa tên riêng <b>Hồng</b>, còn từ chung "sông" viết thường: sông Hồng.'}},{t:"say",text:"Quy tắc 3: Tên nước ngoài. Tên đọc theo âm Hán Việt thì viết như tên Việt: <b>Trung Quốc, Nhật Bản, Thái Lan</b>. Tên phiên âm theo cách đọc của nước đó thì viết hoa chữ đầu, các tiếng nối bằng <b>gạch ngang</b>: <b>Pa-ri, Mát-xcơ-va</b>."},{t:"try",q:{text:"Viết tên phiên âm như <b>Pa-ri</b> (thủ đô nước Pháp), ta viết hoa chữ nào?",opts:["Chữ cái đầu của mỗi tiếng","Chữ cái đầu tiên của tên","Không viết hoa chữ nào"],ans:1,hint:'Nhìn kĩ: chữ "ri" trong Pa-ri có viết hoa không?',why:"Tên phiên âm chỉ viết hoa <b>chữ cái đầu tiên</b>, các tiếng nối bằng gạch ngang: Pa-ri (không viết Pa-Ri)."}},{t:"try",q:{text:'Câu "bạn lan quê ở huế." phải viết hoa mấy chữ cái? Gõ số.',input:!0,ans:"3",hint:"Đếm: chữ đầu câu, tên người, tên địa danh.",why:"Viết hoa 3 chữ: <b>B</b>ạn (đầu câu), <b>L</b>an (tên người), <b>H</b>uế (tên địa lí)."}},{t:"tip",text:"• Tên người, tên địa lí Việt Nam: viết hoa chữ đầu <b>mỗi tiếng</b>.<br>• Từ chung sông, núi, hồ, tỉnh: viết thường (sông Hồng).<br>• Tên nước ngoài đọc âm Hán Việt: viết như tên Việt (Nhật Bản).<br>• Tên phiên âm: viết hoa chữ đầu, nối bằng gạch ngang (Pa-ri)."}],practice:[{id:"tv3.ct-viethoa.1",text:'Đức viết tên mình: "Phạm minh Đức". Bạn cần sửa gì?',opts:['Viết hoa chữ "minh"','Viết thường chữ "Phạm"','Viết thường chữ "Đức"',"Không cần sửa"],ans:0,why:'Tên người viết hoa chữ đầu cả 3 tiếng: <b>Phạm Minh Đức</b>. Chỉ cần sửa chữ "minh".'},{id:"tv3.ct-viethoa.2",text:'Câu "Em đi thăm Núi ba Vì." viết sai ở đâu?',opts:['Chỉ sai chữ "Núi"','Chỉ sai chữ "ba"','Sai cả "Núi" và "ba"',"Không có chữ nào viết sai"],ans:2,why:'Từ chung "núi" viết thường; tên riêng <b>Ba Vì</b> viết hoa cả hai tiếng. Viết đúng: Em đi thăm núi Ba Vì.'},{id:"tv3.ct-viethoa.3",text:'Tên nước "Hàn Quốc" đọc theo âm Hán Việt. Ta viết hoa thế nào?',opts:["Chỉ viết hoa chữ H đầu tên","Viết hoa chữ đầu mỗi tiếng","Viết hoa tất cả các chữ cái","Viết hoa và thêm gạch nối"],ans:1,why:"Tên đọc theo âm Hán Việt viết như tên Việt: viết hoa chữ đầu <b>mỗi tiếng</b>: Hàn Quốc."},{id:"tv3.ct-viethoa.4",text:'Câu "mùa hè, gia đình bạn hà đi biển nha trang." cần viết hoa mấy chữ cái? Gõ số.',input:!0,ans:"4",why:'Viết hoa 4 chữ: <b>M</b>ùa (đầu câu), <b>H</b>à (tên người), <b>N</b>ha <b>T</b>rang (tên địa lí). Từ chung "biển" viết thường.'},{id:"tv3.ct-viethoa.5",text:"Tên thủ đô nước Nga viết thế nào là <b>đúng</b>?",opts:["Mát xcơ va","Mátxcơva","Mát-xcơ-va"],ans:2,why:"Tên phiên âm: viết hoa chữ cái đầu tên, các tiếng nối bằng gạch ngang: <b>Mát-xcơ-va</b>."}]}]},{id:"dochieu3",name:"Đọc hiểu",en:"Reading",icon:"📚",color:"#3d6ef7",lessons:[{id:"tv3.doc-ychinh",title:"Chi tiết và ý chính của đoạn",emoji:"🌳",min:5,who:"rabbit",cards:[{t:"say",pose:"wave",text:"Chào em, Thỏ Bông đây! Lên lớp 3, đọc hiểu không chỉ là tìm <b>chi tiết</b>. Em còn phải biết <b>cả đoạn nói về điều gì</b>: đó là <b>ý chính</b>."},{t:"pic",svg:h("Cây gạo đầu làng","Đầu làng em có một cây gạo già. Thân cây to, ba bạn nhỏ ôm không xuể. Tháng ba, cây gạo nở hoa đỏ rực như ngàn ngọn đuốc. Chim sáo, chim sẻ kéo về ríu rít trên cành. Chiều chiều, các bác nông dân đi làm đồng về thường dừng chân nghỉ dưới gốc cây. Với người dân làng em, cây gạo như một người bạn thân thiết."),cap:"Em đọc kĩ đoạn văn nhé. Các câu hỏi sau đều dựa vào bài này."},{t:"try",q:{text:"Cây gạo nở hoa vào <b>tháng mấy</b>?",opts:["Tháng một","Tháng ba","Tháng năm","Tháng tám"],ans:1,hint:'Tìm câu có từ "nở hoa".',why:"Bài viết: “<b>Tháng ba</b>, cây gạo nở hoa đỏ rực…”"}},{t:"try",q:{text:"Hoa gạo đỏ rực được <b>so sánh</b> với gì?",opts:["Ngàn ngọn đuốc","Đám mây hồng","Chiếc ô đỏ","Ông mặt trời"],ans:0,hint:'Tìm từ "như" trong câu tả hoa gạo.',why:"Bài viết: hoa đỏ rực <b>như ngàn ngọn đuốc</b>."}},{t:"say",text:"Muốn tìm <b>ý chính</b>, em tự hỏi: <b>cả đoạn</b> nói về ai, về cái gì? Các chi tiết đều hướng về điều đó, giống các nan quạt cùng chụm về một chỗ."},{t:"steps",title:'Tìm ý chính của đoạn "Cây gạo đầu làng"',items:[{text:"Các câu nói về: thân cây, hoa, chim về đậu, người nghỉ dưới gốc."},{text:"Tất cả đều xoay quanh <b>cây gạo</b>."},{text:"Câu cuối gói lại: cây gạo như một người bạn thân thiết."},{text:"Ý chính: <b>Cây gạo đầu làng đẹp và gắn bó với người dân.</b>"}]},{t:"try",q:{text:"<b>Ý chính</b> của đoạn văn là gì?",opts:["Chim sáo hót rất hay.","Các bác nông dân đi làm đồng rất vất vả.","Cây gạo đầu làng gắn bó với dân làng.","Làng em có nhiều cây."],ans:2,hint:"Chọn ý nói được về <b>cả đoạn</b>, không chỉ một câu.",why:"Cả đoạn đều nói về cây gạo và sự gắn bó của nó với dân làng. Chim sáo, bác nông dân chỉ là chi tiết."}},{t:"tap",text:"Chạm vào các chi tiết tả <b>hoa gạo</b>.",svg:t(["*nở tháng ba","thân to","*đỏ rực","chim ríu rít","*như ngàn ngọn đuốc","gốc cây"]),need:3,done:"Hoa gạo: <b>nở tháng ba, đỏ rực, như ngàn ngọn đuốc</b>. Thân to, gốc cây là chi tiết về cây; chim ríu rít là chi tiết về chim."},{t:"say",text:"Mẹo: ý chính hay nằm ở <b>câu đầu</b> hoặc <b>câu cuối</b> đoạn. Nhưng em vẫn phải đọc hết đoạn để chắc chắn."},{t:"tip",text:"• <b>Chi tiết</b>: trả lời Ai? Cái gì? Khi nào? Ở đâu? Như thế nào?<br>• <b>Ý chính</b>: cả đoạn nói về điều gì.<br>• Ý chính hay nằm ở câu đầu hoặc câu cuối đoạn.<br>• Đừng chọn ý chỉ đúng với một câu."}],practice:[{id:"tv3.doc-ychinh.1",text:"Đọc bài rồi trả lời: các bạn nữ chơi gì?",svg:a,opts:["Đá cầu","Nhảy dây","Đọc truyện","Kéo co"],ans:1,why:"Bài viết: “Dưới gốc bàng, mấy bạn nữ chơi <b>nhảy dây</b>.”"},{id:"tv3.doc-ychinh.2",text:"Mấy bạn lớp một làm gì?",svg:a,opts:["Đá cầu ở góc sân","Nhảy dây dưới gốc bàng","Tưới nước cho cây trong bồn hoa","Chụm đầu xem truyện tranh"],ans:3,why:"Bài viết: “Mấy bạn lớp một thì ngồi quanh bồn hoa, <b>chụm đầu xem truyện tranh</b>.”"},{id:"tv3.doc-ychinh.3",text:"Bím tóc của các bạn nữ được so sánh với gì?",svg:a,opts:["Những cánh bướm","Những cánh chim","Những sợi dây","Những bông hoa"],ans:0,why:"Bài viết: bím tóc tung lên <b>như những cánh bướm</b>."},{id:"tv3.doc-ychinh.4",text:"<b>Ý chính</b> của đoạn văn là gì?",svg:a,opts:["Các bạn nam say sưa đá cầu ở góc sân bên kia.","Sân trường có cây bàng to.","Giờ ra chơi vui nhộn trên sân trường.","Tiếng trống trường rất to."],ans:2,why:"Cả đoạn kể các bạn vui chơi trong <b>giờ ra chơi</b>. Đá cầu, cây bàng, tiếng trống chỉ là chi tiết."},{id:"tv3.doc-ychinh.5",text:"Xếp các việc theo đúng thứ tự trong bài.",svg:a,...c(["Trống ra chơi vang lên.","Các bạn vui chơi khắp sân.","Cả trường vào lớp học."]),ph:"Chạm các câu theo thứ tự trước → sau",why:"Trống vang lên → các bạn vui chơi → hết giờ, cả trường vào lớp."}]},{id:"tv3.doc-nhanvat",title:"Nhân vật và tính cách",emoji:"🧒",min:6,who:"eleph",cards:[{t:"say",pose:"wave",text:"Chào em, Voi Bi đây! Câu chuyện nào cũng có <b>nhân vật</b>. Muốn biết nhân vật <b>là người thế nào</b>, em nhìn vào <b>việc làm</b> và <b>lời nói</b> của họ."},{t:"pic",svg:h("Bạn mới","Lớp 3A có bạn mới tên là Tú. Tú ở vùng biển chuyển về, nói giọng hơi khác, nhiều bạn nghe thấy lạ. Mấy bạn cười khúc khích. Riêng Hương chạy lại, mời Tú cùng chơi ô ăn quan. Hương còn kiên nhẫn chỉ cho Tú đường đến thư viện, nhà ăn. Mấy hôm sau, Tú đã quen trường, hay cười hơn. Tú bảo: “Nhờ có Hương, tớ không còn thấy lạ nữa.”"),cap:"Đọc kĩ để biết các nhân vật đã <b>làm gì, nói gì</b>."},{t:"try",q:{text:"Ai là bạn mới của lớp 3A?",opts:["Hương","Tú","Lan","Minh"],ans:1,hint:"Đọc lại câu đầu tiên của bài.",why:"Câu đầu: “Lớp 3A có bạn mới tên là <b>Tú</b>.”"}},{t:"say",text:"Bí kíp: <b>việc làm + lời nói → tính cách</b>. Ví dụ: nhường đồ chơi cho em → <b>tốt bụng</b>. Ngày nào cũng dậy sớm tập thể dục → <b>chăm chỉ</b>."},{t:"try",q:{text:"Hương đã làm gì khi thấy bạn mới?",opts:["Cười khúc khích","Mời Tú cùng chơi","Đứng nhìn từ xa","Kể chuyện cho cô"],ans:1,hint:'Tìm câu bắt đầu bằng "Riêng Hương…".',why:"Bài viết: “Riêng Hương chạy lại, <b>mời Tú cùng chơi</b> ô ăn quan.” Cười khúc khích là việc của mấy bạn khác."}},{t:"try",q:{text:"Qua việc làm đó, em thấy Hương là bạn <b>thế nào</b>?",opts:["Nhút nhát, ít nói","Thân thiện, tốt bụng","Nghịch ngợm, hay trêu","Chăm học, giỏi toán"],ans:1,hint:"Người chủ động làm quen và giúp đỡ bạn mới là người thế nào?",why:"Hương mời bạn chơi, chỉ đường cho bạn: Hương <b>thân thiện, tốt bụng</b>."}},{t:"tap",text:"Chạm vào các từ chỉ <b>tính cách</b> (tính nết) của người.",svg:t(["*chăm chỉ","cao lớn","*hiền lành","tóc dài","*dũng cảm","chạy nhảy","*trung thực","mũm mĩm"]),need:4,done:"<b>chăm chỉ, hiền lành, dũng cảm, trung thực</b> là tính cách. Cao lớn, tóc dài, mũm mĩm tả hình dáng; chạy nhảy là hoạt động."},{t:"say",text:"Nhân vật cũng có lúc <b>thay đổi</b>. Như Tú: lúc đầu thấy lạ, sau thì quen trường, hay cười hơn. Em để ý xem <b>nhờ đâu</b> nhân vật thay đổi."},{t:"try",q:{text:"Vì sao Tú không còn thấy lạ nữa?",opts:["Vì Tú chuyển trường khác","Vì cô giáo cho Tú quà","Vì Tú được nghỉ học","Vì có Hương giúp đỡ"],ans:3,hint:"Đọc lời Tú nói ở cuối bài.",why:"Tú nói: “<b>Nhờ có Hương</b>, tớ không còn thấy lạ nữa.”"}},{t:"steps",title:"Cách trả lời câu hỏi về nhân vật",items:[{text:"Bước 1: Tìm câu kể <b>việc làm, lời nói</b> của nhân vật."},{text:"Bước 2: Tự hỏi: người làm vậy là người thế nào?"},{text:"Bước 3: Chọn từ chỉ tính cách: tốt bụng, chăm chỉ, dũng cảm, trung thực, lười biếng…"},{text:'Bước 4: Nêu lí do: "Em thấy Hương tốt bụng <b>vì</b> bạn ấy giúp đỡ bạn mới."'}]},{t:"tip",text:"• Tính cách nhân vật lộ ra qua <b>việc làm</b> và <b>lời nói</b>.<br>• Từ chỉ tính cách: tốt bụng, chăm chỉ, dũng cảm, trung thực…<br>• Khi trả lời, nhớ nêu <b>lí do</b> (vì sao em thấy vậy)."}],practice:[{id:"tv3.doc-nhanvat.1",text:"Đọc truyện rồi xếp các việc theo đúng thứ tự.",svg:u,...c(["Nam nhặt được chiếc ví.","Nam mang ví đến đồn công an.","Một bác đến trường cảm ơn Nam."]),ph:"Chạm các câu theo thứ tự trước → sau",why:"Nhặt được ví → mang đến đồn công an → hôm sau có bác đến cảm ơn."},{id:"tv3.doc-nhanvat.2",text:"Nam đã làm gì với chiếc ví?",svg:u,opts:["Lấy tiền mua kem","Mang đến đồn công an","Giữ lại cất vào cặp","Đưa cho Tuấn"],ans:1,why:"Bài viết: “Nam mang chiếc ví <b>đến đồn công an</b> gần nhà.”"},{id:"tv3.doc-nhanvat.3",text:"Câu nói nào cho thấy Nam <b>biết nghĩ cho người khác</b>?",svg:u,opts:["“Hay mình lấy tiền mua kem ăn đi!”","“Lần sau tớ sẽ làm giống cậu.”","“Người mất chắc đang lo lắm.”","“Tớ sai rồi.”"],ans:2,why:'Nam nghĩ tới nỗi lo của <b>người mất ví</b>. Hai câu "Tớ sai rồi", "Lần sau…" là của Tuấn.'},{id:"tv3.doc-nhanvat.4",text:"Nam là người như thế nào?",svg:u,opts:["Lười biếng","Nhút nhát","Keo kiệt","Trung thực"],ans:3,why:"Nhặt được của rơi, Nam tìm cách trả lại người mất: Nam <b>trung thực</b>."},{id:"tv3.doc-nhanvat.5",text:"Cuối truyện, Tuấn thay đổi thế nào?",svg:u,opts:["Tuấn nhận ra mình sai","Tuấn giận Nam, không chơi nữa","Tuấn đi mua kem","Tuấn khoe với cô"],ans:0,why:"Tuấn đỏ mặt, nói: “Tớ sai rồi. Lần sau tớ sẽ làm giống cậu.” Tuấn đã <b>nhận ra mình sai</b>."}]},{id:"tv3.doc-baihoc",title:"Bài học rút ra từ câu chuyện",emoji:"🌱",min:5,who:"lion",cards:[{t:"say",pose:"wave",text:"Chào em, Sư Tử Vua đây! Mỗi câu chuyện như một món quà, bên trong gói một <b>bài học</b>. Hôm nay mình học cách <b>mở quà</b> nhé!"},{t:"pic",svg:h("Hai cây non","Bên bờ suối có hai cây non. Cây thứ nhất lặng lẽ vươn rễ thật sâu xuống đất. Cây thứ hai chỉ lo mọc thật nhiều lá xanh để khoe với mọi người. Nó cười cây bạn: “Cậu chậm chạp quá!” Một đêm, gió bão nổi lên. Cây thứ hai bật cả gốc, nằm rạp bên bờ suối. Cây thứ nhất vẫn đứng vững nhờ bộ rễ chắc khoẻ. Sáng ra, cây ấy lại vươn những chiếc lá non đón nắng."),cap:"Đọc kĩ để thấy hai cây khác nhau ở đâu."},{t:"try",q:{text:"Cây thứ nhất lo làm gì?",opts:["Mọc thật nhiều lá","Vươn rễ thật sâu","Nở thật nhiều hoa","Cười cây bạn"],ans:1,hint:'Tìm câu có "Cây thứ nhất".',why:"Bài viết: “Cây thứ nhất lặng lẽ <b>vươn rễ thật sâu</b> xuống đất.”"}},{t:"try",q:{text:"Khi gió bão nổi lên, cây thứ hai ra sao?",opts:["Bật cả gốc","Rụng hết hoa","Vẫn đứng vững","Mọc thêm lá"],ans:0,hint:'Tìm câu ngay sau "gió bão nổi lên".',why:"Bài viết: “Cây thứ hai <b>bật cả gốc</b>, nằm rạp bên bờ suối.”"}},{t:"say",text:"Muốn tìm bài học, em so sánh: nhân vật nào <b>thành công</b>, nhân vật nào <b>gặp chuyện không hay</b>? <b>Vì sao</b> lại như vậy?"},{t:"steps",title:"Mở món quà bài học",items:[{text:"Cây thứ nhất lo bộ rễ → đứng vững qua bão."},{text:"Cây thứ hai chỉ lo khoe lá, chê bạn → bị bật gốc."},{text:"Vì sao? Rễ là gốc, giúp cây đứng vững. Lá đẹp mà gốc yếu thì không chịu được bão."},{text:"Bài học: <b>Cần chăm lo cái gốc cho vững chắc, đừng chỉ khoe vẻ ngoài, đừng chê bai bạn.</b>"}]},{t:"try",q:{text:"Câu chuyện muốn khuyên em điều gì?",opts:["Nên trồng thật nhiều cây bên bờ suối.","Khi có gió bão, nên ở yên trong nhà cho an toàn.","Cần chăm lo cái gốc, đừng chỉ khoe vẻ ngoài.","Cây có nhiều lá xanh là cây đẹp nhất."],ans:2,hint:"Bài học rút ra từ việc: cây nào đứng vững, vì sao.",why:"Cây có rễ sâu thì đứng vững. Bài học: <b>chăm lo cái gốc</b> (như học cho thật chắc), đừng chỉ khoe vẻ bề ngoài."}},{t:"say",text:"Bài học thường có các từ: <b>cần, nên, phải, hãy, đừng, không nên</b>. Đó là lời khuyên cho <b>mọi người</b>, không chỉ cho nhân vật."},{t:"tap",text:"Chạm vào các câu là <b>bài học</b> (lời khuyên), không phải chi tiết trong truyện.",svg:t(["*Phải biết giữ lời hứa.","Thỏ chạy rất nhanh.","*Cần chăm chỉ mỗi ngày.","Trời đổ mưa to.","*Đừng chê bai người khác."]),need:3,done:'Ba câu có <b>phải, cần, đừng</b> là lời khuyên. "Thỏ chạy rất nhanh", "Trời đổ mưa to" chỉ kể chi tiết.'},{t:"try",q:{text:"Câu nào nêu <b>bài học</b>?",opts:["Cây thứ hai nằm rạp bên suối.","Đừng chê bai, cười nhạo bạn bè.","Sáng ra, trời lại có nắng."],ans:1,hint:"Tìm câu có từ khuyên bảo: cần, nên, hãy, đừng…",why:'"<b>Đừng</b> chê bai, cười nhạo bạn bè." là lời khuyên. Hai câu kia kể chi tiết.'}},{t:"tip",text:"• So sánh: ai thành công, ai gặp chuyện không hay, <b>vì sao</b>.<br>• Bài học là <b>lời khuyên cho mọi người</b>.<br>• Bài học hay có từ: cần, nên, phải, hãy, đừng."}],practice:[{id:"tv3.doc-baihoc.1",text:"Đọc truyện rồi trả lời: lúc đầu, vì sao Thỏ Nâu chỉ dám ngồi trên bờ?",svg:o,opts:["Vì Thỏ sợ nước","Vì Thỏ bị ốm","Vì trời quá lạnh","Vì Vịt cấm Thỏ"],ans:0,why:"Bài viết: Thỏ Nâu muốn học bơi <b>nhưng lại sợ nước</b>."},{id:"tv3.doc-baihoc.2",text:"Vịt Bầu khuyên Thỏ điều gì?",svg:o,opts:["Bỏ không học nữa","Tập từng chút một","Chỉ tập vào mùa đông","Nhờ bạn bơi giúp"],ans:1,why:"Vịt dặn: “Cậu cứ <b>tập từng chút một</b>.”"},{id:"tv3.doc-baihoc.3",text:"Chi tiết nào cho thấy Thỏ Nâu <b>không bỏ cuộc</b>?",svg:o,opts:["Hôm đầu, Thỏ chỉ dám ngồi trên bờ.","Cả khu rừng vỗ tay khen ngợi Thỏ.","Bị sặc nước, hôm sau Thỏ vẫn đến.","Thỏ Nâu rất muốn học bơi."],ans:2,why:"Bị sặc nước, mắt đỏ hoe mà <b>hôm sau vẫn đến</b> tập: Thỏ không bỏ cuộc."},{id:"tv3.doc-baihoc.4",text:"Câu chuyện khuyên em điều gì?",svg:o,opts:["Chỉ nên học những gì mình đã giỏi.","Mùa hè nên rủ bạn ra hồ bơi chơi.","Sợ thì đừng cố gắng làm gì.","Kiên trì tập luyện thì sẽ làm được."],ans:3,why:"Thỏ sợ nước nhưng chăm tập mỗi ngày nên đã bơi được. Bài học: <b>kiên trì</b> thì sẽ thành công."},{id:"tv3.doc-baihoc.5",text:"Xếp các câu theo đúng thứ tự trong truyện.",svg:o,...c(["Thỏ chỉ dám ngồi trên bờ.","Ngày nào Thỏ cũng tập bơi.","Thỏ bơi được một vòng hồ."]),ph:"Chạm các câu theo thứ tự trước → sau",why:"Lúc đầu ngồi trên bờ → ngày nào cũng tập → cuối hè bơi được một vòng hồ."}]},{id:"tv3.doc-tungu",title:"Hiểu từ ngữ và hình ảnh so sánh",emoji:"🏞️",min:6,who:"monkey",cards:[{t:"say",pose:"wave",text:"Chào em, Khỉ Tít đây! Trong bài đọc có những <b>từ ngữ hay</b> và những <b>hình ảnh so sánh</b> đẹp. Hiểu được chúng, em sẽ thấy bài văn sinh động hẳn lên!"},{t:"pic",svg:h("Dòng sông quê em","Dòng sông quê em hiền hoà chảy qua cánh đồng lúa. Buổi sáng, mặt sông lấp lánh như dát bạc. Hai bên bờ, những rặng tre xanh rì rào trong gió. Trưa hè, lũ trẻ nô đùa dưới sông, tiếng cười giòn tan. Chiều về, những cánh buồm nâu nhấp nhô như đàn bướm khổng lồ. Em yêu dòng sông như yêu một người bạn đã cùng em lớn lên."),cap:"Đọc kĩ, để ý các từ ngữ tả dòng sông."},{t:"say",text:"Muốn hiểu nghĩa một từ, em đọc <b>cả câu có từ đó</b>, rồi thử <b>thay</b> bằng từ khác xem câu có giữ nguyên ý không."},{t:"try",q:{text:'Từ <b>hiền hoà</b> trong câu "Dòng sông quê em hiền hoà chảy qua cánh đồng lúa" có nghĩa là gì?',opts:["Chảy rất xiết","Êm đềm, dịu dàng","Rộng mênh mông","Đục ngầu"],ans:1,hint:'Thử thay từng ý vào câu. Ý nào hợp với một dòng sông "hiền"?',why:'<b>hiền hoà</b>: êm đềm, dịu dàng, không dữ dội. Thay vào: "Dòng sông êm đềm chảy qua cánh đồng."'}},{t:"say",text:"Hình ảnh <b>so sánh</b> đặt hai sự vật cạnh nhau, nối bằng các từ <b>như, tựa, giống như, là</b>. Ví dụ: mặt sông lấp lánh <b>như</b> dát bạc."},{t:"tap",text:"Chạm vào các <b>từ so sánh</b>.",svg:t(["Mặt","sông","*như","dát","bạc.","Cánh","buồm","*tựa","đàn","bướm.","Trăng","tròn","*như","cái","đĩa."]),need:3,done:"<b>như, tựa, như</b> là từ so sánh: chúng nối hai sự vật giống nhau."},{t:"steps",title:"Tìm cái hay của một hình ảnh so sánh",items:[{text:"Bước 1: Tìm hai sự vật được so sánh: <b>cánh buồm nâu</b> – <b>đàn bướm khổng lồ</b>."},{text:"Bước 2: Tìm điểm giống: cùng nhấp nhô, chao lượn."},{text:"Bước 3: Nói cái hay: những cánh buồm hiện lên <b>sinh động</b>, như đang bay trên sông."}]},{t:"try",q:{text:"Trong bài, những cánh buồm nâu được so sánh với gì?",opts:["Đàn bướm khổng lồ","Những đám mây trắng","Rặng tre xanh","Mặt sông"],ans:0,hint:'Tìm câu có "cánh buồm", rồi xem sau từ "như".',why:"Bài viết: cánh buồm nâu nhấp nhô <b>như đàn bướm khổng lồ</b>."}},{t:"try",q:{text:'Từ <b>giòn tan</b> trong "tiếng cười giòn tan" tả tiếng cười thế nào?',opts:["Nhỏ và buồn","To, khàn và đầy giận dữ","Trong trẻo, vui vẻ","Khàn khàn"],ans:2,hint:"Lũ trẻ đang nô đùa thì tiếng cười nghe thế nào?",why:"<b>giòn tan</b>: tiếng cười trong, vang, nghe rất vui."}},{t:"try",q:{text:'Câu "Em yêu dòng sông như yêu một người bạn" cho thấy điều gì?',opts:["Em sợ dòng sông khi mùa lũ về","Em rất yêu quý dòng sông","Dòng sông rộng như biển","Em có nhiều bạn ở bờ sông"],ans:1,hint:"Em so sánh tình yêu dòng sông với tình cảm dành cho ai?",why:"So sánh với tình bạn cho thấy em <b>gắn bó, yêu quý</b> dòng sông như một người bạn."}},{t:"tip",text:"• Hiểu nghĩa từ: đọc cả câu, thử thay bằng từ khác.<br>• So sánh có từ nối: <b>như, tựa, giống như, là</b>.<br>• Cái hay: tìm hai sự vật, điểm giống nhau, hình ảnh hiện lên ra sao."}],practice:[{id:"tv3.doc-tungu.1",text:"Đọc bài thơ rồi trả lời: mưa xuân được so sánh với gì?",svg:m,opts:["Sợi chỉ mỏng manh","Hạt cườm","Cánh én","Những chú lính canh"],ans:0,why:"Thơ viết: Mưa xuân rơi nhè nhẹ / <b>Như sợi chỉ mỏng manh</b>."},{id:"tv3.doc-tungu.2",text:'Từ <b>nhú</b> trong dòng "Nhú lộc biếc trên cành" nghĩa là gì?',svg:m,opts:["Rụng xuống đất","Héo khô dần","Mới mọc ra một chút","Đung đưa trong gió"],ans:2,why:"<b>nhú</b>: mới mọc ra, mới hiện ra một chút. Mưa xuân làm cây bàng nhú lộc non."},{id:"tv3.doc-tungu.3",text:"Vì sao hàng cau được so sánh với <b>những chú lính canh</b>?",svg:m,opts:["Vì cau có quả xanh và lá nâu","Vì cau thấp bé, nằm rạp xuống","Vì cau đứng thẳng như gác cổng","Vì cau biết hát như chú lính"],ans:2,why:"Hàng cau <b>đứng thẳng</b> ngoài ngõ, giống các chú lính đứng canh gác."},{id:"tv3.doc-tungu.4",text:"Bàn tay bé xoè ra đón mưa được so sánh với gì?",svg:m,opts:["Sợi chỉ","Hạt cườm","Lộc biếc","Cánh én"],ans:3,why:"Thơ viết: Tay xoè <b>như cánh én</b>."},{id:"tv3.doc-tungu.5",text:"Cả bài thơ có mấy hình ảnh so sánh dùng từ <b>như</b>? Gõ số.",svg:m,input:!0,ans:"4",why:"Có 4: mưa <b>như</b> sợi chỉ; hàng cau <b>như</b> chú lính canh; hạt mưa long lanh <b>như</b> hạt cườm; tay xoè <b>như</b> cánh én."}]}]},{id:"viet3",name:"Viết",en:"Writing",icon:"📝",color:"#8b5cf6",lessons:[{id:"tv3.viet-trainghiem",title:"Kể một trải nghiệm đáng nhớ",emoji:"🥕",min:6,who:"pengu",cards:[{t:"say",pose:"wave",text:"Chào em, Cánh Cụt Pin đây! Một chuyến đi chơi, lần đầu tự đạp xe, một buổi lao động… đều là <b>trải nghiệm</b>. Kể thật hay để ai đọc cũng như được đi cùng em!"},{t:"steps",title:"Dàn ý đoạn văn kể trải nghiệm",items:[{text:"<b>Mở đoạn</b>: Trải nghiệm gì? Khi nào, ở đâu, với ai?"},{text:"<b>Thân đoạn</b>: Kể diễn biến theo thứ tự (Đầu tiên, Sau đó, Cuối cùng). Chọn 1–2 chi tiết đáng nhớ nhất."},{text:"<b>Kết đoạn</b>: Cảm xúc của em và điều em học được."}]},{t:"pic",svg:h("Bài mẫu","Chủ nhật tuần trước, lớp em đi trải nghiệm ở một trang trại trồng rau. Đầu tiên, cô hướng dẫn cho chúng em xem những luống cải xanh mướt. Sau đó, cả lớp được tự tay gieo hạt và tưới nước. Em còn được nhổ mấy củ cà rốt đỏ au mang về. Lúc ra về, tay em lấm đầy đất nhưng ai cũng cười tươi. Em thấy người trồng rau thật vất vả. Từ nay, em sẽ không bỏ thừa rau trong bữa cơm nữa."),cap:"Các từ <b>Đầu tiên, Sau đó, Lúc ra về</b> giữ cho việc kể đúng thứ tự."},{t:"try",q:{text:"Câu mở đoạn của bài mẫu cho biết những gì?",opts:["Cảm xúc của em","Khi nào, ai, đi đâu","Điều em học được","Em nhổ được những củ gì"],ans:1,hint:'Đọc lại câu đầu: "Chủ nhật tuần trước, lớp em đi…"',why:"Câu mở đoạn cho biết <b>khi nào</b> (chủ nhật tuần trước), <b>ai</b> (lớp em), <b>đi đâu</b> (trang trại trồng rau)."}},{t:"say",text:'Đoạn văn hay cần <b>chi tiết</b> làm người đọc như nhìn thấy. Đừng chỉ viết "em nhổ cà rốt", hãy viết "em nhổ mấy củ cà rốt <b>đỏ au</b>".'},{t:"try",q:{text:"Câu nào kể <b>sinh động</b> hơn?",opts:["Em đi thả diều với bạn.","Em chạy ngược gió, diều đỏ vút lên cao."],ans:1,hint:'Câu nào giúp em "nhìn thấy" cảnh thả diều?',why:"Câu thứ hai có chi tiết: <b>chạy ngược gió</b>, <b>diều đỏ vút lên cao</b>. Đọc là thấy ngay cảnh."}},{t:"tap",text:"Chạm vào các <b>từ nối</b> giúp kể đúng thứ tự.",svg:t(["*Đầu tiên,","em","nhặt","rau.","*Sau đó,","em","rửa","rau.","*Cuối cùng,","em","dọn","bàn."]),need:3,done:"<b>Đầu tiên, Sau đó, Cuối cùng</b> là từ nối chỉ thứ tự. Nhờ chúng, người đọc biết việc nào trước, việc nào sau."},{t:"try",q:{text:"Xếp các câu theo đúng thứ tự để thành đoạn văn.",...c(["Sáng chủ nhật, em theo bố đi câu cá.","Đầu tiên, bố dạy em móc mồi.","Sau đó, em ngồi im chờ cá cắn câu.","Cuối cùng, em câu được một chú cá rô."]),ph:"Chạm các câu theo thứ tự",hint:"Câu mở đoạn nói khi nào, việc gì. Sau đó nhìn từ nối.",why:"Mở đoạn (sáng chủ nhật, đi câu cá) → Đầu tiên → Sau đó → Cuối cùng."}},{t:"say",text:"Kết đoạn, nói <b>cảm xúc</b> (vui, hồi hộp, tự hào…) và <b>điều em học được</b>. Đó là phần làm đoạn văn có hồn."},{t:"try",q:{text:"Câu nào hợp làm câu <b>kết đoạn</b>?",opts:["Đầu tiên, cả lớp em xếp hàng lên xe ô tô.","Chuyến đi giúp em thêm yêu thiên nhiên.","Hôm đó là thứ bảy.","Xe đi rất nhanh."],ans:1,hint:"Câu kết nói cảm xúc hoặc điều em học được.",why:'"Chuyến đi giúp em <b>thêm yêu thiên nhiên</b>." nêu điều em nhận được. Câu "Đầu tiên…" là câu kể ở thân đoạn.'}},{t:"tip",text:"• Dàn ý: <b>mở đoạn</b> (khi nào, ở đâu, với ai) → <b>thân đoạn</b> (diễn biến, chi tiết) → <b>kết đoạn</b> (cảm xúc).<br>• Dùng từ nối: Đầu tiên, Sau đó, Cuối cùng.<br>• Thêm chi tiết để người đọc như nhìn thấy.<br>• Kể việc em <b>thật sự</b> đã trải qua."}],practice:[{id:"tv3.viet-trainghiem.1",text:"Đoạn văn kể trải nghiệm thường có mấy phần?",opts:["2 phần","3 phần","4 phần"],ans:1,why:"Có 3 phần: <b>mở đoạn, thân đoạn, kết đoạn</b>."},{id:"tv3.viet-trainghiem.2",text:"Câu nào hợp làm câu <b>mở đoạn</b>?",opts:["Em thấy rất vui.","Sau đó, cả nhà lên xe về thành phố.","Hè vừa rồi, em được về quê ngoại.","Cuối cùng, mọi người chụp ảnh."],ans:2,why:"Câu mở đoạn cho biết <b>khi nào</b> (hè vừa rồi) và <b>trải nghiệm gì</b> (về quê ngoại)."},{id:"tv3.viet-trainghiem.3",text:"Xếp các câu theo đúng thứ tự.",...c(["Đầu tiên, em lấy chậu và đất.","Sau đó, em gieo hạt và tưới nước.","Mấy hôm sau, hạt đã nảy mầm."]),ph:"Chạm các câu theo thứ tự",why:"Đầu tiên chuẩn bị chậu đất → sau đó gieo hạt, tưới nước → mấy hôm sau hạt nảy mầm."},{id:"tv3.viet-trainghiem.4",text:"Câu nào <b>không</b> nên đưa vào đoạn văn kể chuyến đi biển?",opts:["Sóng xô vào bờ trắng xoá.","Em và bố nhặt được nhiều vỏ sò.","Nước biển mằn mặn.","Bạn em có một con mèo tam thể."],ans:3,why:"Con mèo của bạn không liên quan đến chuyến đi biển."},{id:"tv3.viet-trainghiem.5",text:'Chọn từ hợp nhất: "Lần đầu tự đạp xe đến trường, em thấy rất …"',opts:["tự hào","buồn ngủ","đói bụng","ồn ào"],ans:0,why:"Lần đầu tự làm được một việc khó, em thấy <b>tự hào</b>. Đây là từ chỉ cảm xúc hợp với câu."}]},{id:"tv3.viet-ta",title:"Tả đồ vật, con vật, cảnh",emoji:"🐱",min:6,who:"dino",cards:[{t:"say",pose:"wave",text:"Chào em, Khủng Long Rex đây! Tả là dùng lời để <b>vẽ tranh</b>. Đọc xong, người khác phải <b>hình dung</b> được đồ vật, con vật hay cảnh em tả."},{t:"say",text:"Bí kíp: tả bằng <b>nhiều giác quan</b>. Mắt nhìn (màu sắc, hình dáng), tai nghe (tiếng kêu), tay sờ (mềm, cứng), mũi ngửi (thơm, hắc)."},{t:"try",q:{text:'Câu "Bộ lông mèo mềm như nhung" em cảm nhận bằng giác quan nào?',opts:["Mắt nhìn","Tai nghe","Tay sờ","Mũi ngửi"],ans:2,hint:"Làm sao em biết lông mèo mềm hay cứng?",why:'"mềm" là cảm giác khi <b>tay sờ</b> vào bộ lông.'}},{t:"steps",title:"Dàn ý tả con vật",items:[{text:"1. Giới thiệu: con vật gì, của ai, tên là gì?"},{text:"2. Tả hình dáng: bộ lông, đôi mắt, đôi tai, cái đuôi…"},{text:"3. Tả hoạt động, thói quen: ăn, ngủ, chơi thế nào?"},{text:"4. Tình cảm của em với con vật."}]},{t:"pic",svg:h("Bài mẫu","Nhà em nuôi một chú mèo tên là Mướp. Mướp có bộ lông vàng óng như tơ. Hai mắt chú tròn xoe, xanh biếc như hai hòn bi ve. Đôi tai nhỏ luôn vểnh lên nghe ngóng. Ban ngày, Mướp nằm sưởi nắng bên hiên. Ban đêm, chú rón rén đi tuần quanh bếp. Mỗi khi em đi học về, Mướp lại chạy ra cọ đầu vào chân em. Em rất yêu chú mèo nhỏ này."),cap:"Hình ảnh so sánh: lông vàng óng <b>như tơ</b>, mắt <b>như hai hòn bi ve</b>."},{t:"tap",text:"Chạm vào các từ ngữ <b>gợi tả</b> trong bài mẫu.",svg:t(["*vàng óng","nhà em","*tròn xoe","ban ngày","*rón rén","đi học","*xanh biếc","chú mèo"]),need:4,done:"<b>vàng óng, tròn xoe, rón rén, xanh biếc</b> là từ gợi tả: đọc lên là thấy ngay màu sắc, hình dáng, dáng đi."},{t:"try",q:{text:"Trong bài mẫu, đôi mắt của Mướp được so sánh với gì?",opts:["Hai hòn bi ve","Hai ngôi sao","Hai hạt nhãn","Hai giọt nước"],ans:0,hint:'Tìm câu tả đôi mắt, xem sau từ "như".',why:"Bài viết: mắt xanh biếc <b>như hai hòn bi ve</b>."}},{t:"say",text:"Tả <b>đồ vật</b>: tả bao quát (to hay nhỏ, màu gì) rồi tả từng <b>bộ phận</b> và công dụng. Tả <b>cảnh</b>: tả theo thứ tự, từ gần đến xa hoặc từ sáng đến chiều."},{t:"try",q:{text:"Khi tả chiếc cặp sách, câu nào tả <b>bộ phận</b> của cặp?",opts:["Chiếc cặp là quà sinh nhật của mẹ.","Em sẽ giữ gìn cặp thật cẩn thận.","Quai cặp to bản, đeo rất êm vai.","Cặp giúp em đựng sách vở."],ans:2,hint:"Bộ phận là một phần của chiếc cặp: quai, khoá, ngăn…",why:'"<b>Quai cặp</b> to bản…" tả một bộ phận. Các câu còn lại là giới thiệu, tình cảm, công dụng.'}},{t:"try",q:{text:"Xếp các cụm từ thành câu tả có hình ảnh so sánh.",order:[n("Chú gà trống"),"có",n("chiếc mào"),n("đỏ chót"),"như",n("bông râm bụt.")],ans:[n("Chú gà trống"),"có",n("chiếc mào"),n("đỏ chót"),"như",n("bông râm bụt.")].join(" "),hint:"Câu bắt đầu bằng chữ viết hoa; cụm có dấu chấm đứng cuối.",why:"Chú gà trống có chiếc mào đỏ chót <b>như</b> bông râm bụt."}},{t:"tip",text:"• Tả bằng nhiều giác quan: <b>nhìn, nghe, sờ, ngửi</b>.<br>• Con vật: hình dáng → hoạt động → tình cảm.<br>• Đồ vật: bao quát → bộ phận, công dụng → tình cảm.<br>• Dùng từ gợi tả và hình ảnh so sánh cho sinh động."}],practice:[{id:"tv3.viet-ta.1",text:"Khi tả con vật, em thường tả những gì?",opts:["Chỉ tả màu lông","Hình dáng và hoạt động","Chỉ kể tên con vật","Giá tiền khi mua con vật đó"],ans:1,why:"Tả con vật: tả <b>hình dáng</b> (lông, mắt, tai…) và <b>hoạt động</b>, rồi nêu tình cảm."},{id:"tv3.viet-ta.2",text:"Câu nào có hình ảnh <b>so sánh</b>?",opts:["Chú chó nhà em tên là Mực.","Chú chó sủa vang mỗi khi có người lạ đến nhà.","Tai chú chó dựng lên như hai chiếc lá.","Em rất yêu chú chó."],ans:2,why:"Tai chó được so sánh với <b>hai chiếc lá</b>, nối bằng từ <b>như</b>."},{id:"tv3.viet-ta.3",text:'Câu "Tiếng chim hót líu lo trên cành" tả bằng giác quan nào?',opts:["Tai nghe","Mắt nhìn","Mũi ngửi","Tay sờ"],ans:0,why:"Tiếng chim hót <b>líu lo</b> là âm thanh, em cảm nhận bằng <b>tai nghe</b>."},{id:"tv3.viet-ta.4",text:'Đoạn tả bút chì: "Chiếc bút chì dài bằng gang tay. Thân bút sơn màu xanh. Ngòi bút nhọn hoắt." Đoạn còn <b>thiếu</b> ý nào?',opts:["Hình dáng","Màu sắc","Các bộ phận của bút","Tình cảm của em"],ans:3,why:"Đã có hình dáng (dài bằng gang tay), màu sắc (xanh), bộ phận (thân, ngòi). Còn thiếu <b>tình cảm của em</b> với chiếc bút."},{id:"tv3.viet-ta.5",text:"Xếp các cụm từ thành câu tả.",order:[n("Mặt trăng"),n("tròn vành vạnh"),"như",n("chiếc đĩa bạc.")],ans:[n("Mặt trăng"),n("tròn vành vạnh"),"như",n("chiếc đĩa bạc.")].join(" "),why:"Mặt trăng tròn vành vạnh <b>như</b> chiếc đĩa bạc."}]},{id:"tv3.viet-camxuc",title:"Nêu tình cảm, cảm xúc của em",emoji:"💖",min:6,who:"uni",cards:[{t:"say",pose:"wave",text:"Chào em, Kỳ Lân Sao đây! Có người làm em <b>xúc động</b>, có câu chuyện làm em <b>nhớ mãi</b>. Hôm nay mình học viết đoạn văn nói lên <b>tình cảm, cảm xúc</b> của em."},{t:"steps",title:"Dàn ý: nêu tình cảm với một người",items:[{text:"<b>Mở đoạn</b>: Người em muốn nói đến là ai?"},{text:"<b>Thân đoạn</b>: Điều gì ở người đó làm em nhớ (dáng vẻ, việc làm, lời nói)? Kể một kỉ niệm."},{text:"<b>Kết đoạn</b>: Tình cảm của em (yêu quý, biết ơn, khâm phục…) và mong muốn của em."}]},{t:"pic",svg:h("Bài mẫu","Người em yêu quý nhất ở trường là cô Hạnh, cô giáo chủ nhiệm lớp em. Cô có giọng nói ấm áp, dịu dàng. Có lần em bị ốm phải nghỉ học, cô đã đến tận nhà thăm và giảng lại bài cho em. Em cảm động lắm. Em rất biết ơn cô. Em tự hứa sẽ chăm ngoan, học giỏi để cô vui lòng."),cap:"Bài mẫu kể một <b>kỉ niệm</b> rồi mới nói tình cảm."},{t:"try",q:{text:"Câu nào trong bài mẫu nói lên <b>tình cảm</b> của em?",opts:["Cô có giọng nói ấm áp, dịu dàng.","Em rất biết ơn cô.","Cô đến tận nhà thăm em.","Cô Hạnh là cô chủ nhiệm."],ans:1,hint:"Tìm câu có từ chỉ tình cảm: yêu, thương, biết ơn…",why:'"Em rất <b>biết ơn</b> cô." nói tình cảm. Các câu khác tả cô hoặc kể việc cô làm.'}},{t:"tap",text:"Chạm vào các từ chỉ <b>tình cảm, cảm xúc</b>.",svg:t(["*biết ơn","giọng nói","*cảm động","giảng bài","*kính yêu","tóc dài","*khâm phục","đến thăm"]),need:4,done:"<b>biết ơn, cảm động, kính yêu, khâm phục</b> chỉ tình cảm, cảm xúc. Các từ còn lại tả dáng vẻ hoặc việc làm."},{t:"say",text:'Muốn tình cảm <b>thật</b>, em kể một <b>việc cụ thể</b>. Viết "Em yêu bà" là chưa đủ. Hãy kể "Đêm hè, bà ngồi quạt cho em ngủ" rồi mới nói "Em yêu bà lắm".'},{t:"try",q:{text:"Câu nào giúp người đọc <b>hiểu vì sao</b> em biết ơn bác bảo vệ?",opts:["Bác bảo vệ trường em tên là bác Tư.","Sáng nào bác cũng dắt xe giúp chúng em.","Bác có mái tóc hoa râm, dáng cao gầy.","Em mong bác luôn mạnh khoẻ."],ans:1,hint:"Tìm câu kể <b>việc tốt</b> bác đã làm cho em.",why:'"Sáng nào bác cũng <b>dắt xe giúp</b> chúng em." là việc làm khiến em biết ơn.'}},{t:"say",text:"Viết về <b>nhân vật em thích</b> trong một câu chuyện: nêu tên nhân vật và tên truyện → kể việc làm đáng nhớ → nói <b>vì sao</b> em thích, em học được gì."},{t:"pic",svg:h("Bài mẫu","Trong truyện Thánh Gióng, em thích nhất nhân vật Gióng. Gióng lên ba tuổi vẫn chưa biết nói, nhưng khi nghe tin giặc đến, Gióng đã xin đi đánh giặc. Roi sắt gãy, Gióng nhổ cả bụi tre bên đường quật vào giặc. Em thích Gióng vì Gióng dũng cảm, yêu đất nước. Em sẽ cố gắng học giỏi để sau này góp sức xây dựng quê hương."),cap:"Chú ý từ <b>vì</b>: sau nó là lí do em thích nhân vật."},{t:"try",q:{text:"Trong bài mẫu, vì sao bạn nhỏ thích Gióng?",opts:["Vì Gióng ăn rất khoẻ","Vì Gióng dũng cảm, yêu nước","Vì Gióng có ngựa sắt","Vì Gióng lên ba chưa biết nói"],ans:1,hint:'Tìm câu có từ "vì" trong bài mẫu.',why:"Bài viết: “Em thích Gióng <b>vì Gióng dũng cảm, yêu đất nước</b>.”"}},{t:"try",q:{text:"Nêu lí do <b>không thích</b> một nhân vật, câu nào hợp?",opts:["Em không thích cáo vì nó gian xảo, lừa bạn.","Con cáo sống ở trong một cái hang sâu giữa khu rừng.","Con cáo có bộ lông đỏ và cái đuôi dài.","Cáo chạy rất nhanh."],ans:0,hint:'Câu cần có cả "không thích" và lí do (vì…).',why:"Câu đầu nêu rõ em <b>không thích</b> cáo và <b>lí do</b>: nó gian xảo, lừa bạn. Các câu khác chỉ tả con cáo."}},{t:"tip",text:"• Kể một <b>việc cụ thể</b> trước, rồi nói tình cảm.<br>• Từ chỉ tình cảm: yêu quý, biết ơn, kính yêu, khâm phục, cảm động.<br>• Nói về nhân vật: tên nhân vật, việc làm, <b>vì sao</b> em thích (hoặc không thích)."}],practice:[{id:"tv3.viet-camxuc.1",text:"Đoạn văn nêu tình cảm với người thân nên kết thúc bằng ý nào?",opts:["Tên của người đó","Hình dáng, tuổi tác của người đó","Tình cảm và mong muốn của em","Nơi ở của người đó"],ans:2,why:"Kết đoạn nói <b>tình cảm</b> và <b>mong muốn</b> của em. Tên người nói ở mở đoạn; hình dáng ở thân đoạn."},{id:"tv3.viet-camxuc.2",text:"Từ nào chỉ <b>tình cảm</b>?",opts:["thương yêu","tóc bạc","chăm chỉ","cao gầy"],ans:0,why:"<b>thương yêu</b> chỉ tình cảm. Chăm chỉ là tính cách; tóc bạc, cao gầy tả dáng vẻ."},{id:"tv3.viet-camxuc.3",text:'Câu nào nêu <b>lí do</b> em thích nhân vật Nam trong truyện "Chiếc ví đánh rơi"?',opts:["Truyện kể về hai bạn Nam và Tuấn trên đường đi học.","Em thích Nam vì bạn ấy rất trung thực.","Nam mang chiếc ví đến đồn công an.","Tuấn rủ Nam đi mua kem."],ans:1,why:"Câu có từ <b>vì</b> nêu lí do: Nam rất trung thực. Các câu khác chỉ kể lại truyện."},{id:"tv3.viet-camxuc.4",text:"Xếp các câu thành đoạn văn: mở đoạn → thân đoạn → kết đoạn.",...c(["Người em yêu quý nhất là ông nội.","Ông thường dạy em chơi cờ.","Em mong ông luôn khoẻ mạnh."]),ph:"Chạm các câu theo thứ tự",why:"Mở đoạn: người đó là ai → thân đoạn: việc ông làm → kết đoạn: mong muốn của em."},{id:"tv3.viet-camxuc.5",text:'Bạn viết: "Mẹ em rất hiền. Em yêu mẹ." Nên thêm câu nào để đoạn văn cảm động hơn?',opts:["Mẹ em năm nay ba mươi lăm tuổi.","Nhà em ở gần chợ, sáng nào mẹ cũng đi chợ thật sớm.","Mẹ em có chiếc xe đạp màu xanh.","Đêm em sốt, mẹ thức trắng chườm khăn cho em."],ans:3,why:"Câu kể <b>việc cụ thể</b> mẹ chăm em lúc ốm làm người đọc hiểu vì sao em yêu mẹ."}]},{id:"tv3.viet-vanban",title:"Viết thư, giấy mời, thông báo, đơn",emoji:"✉️",min:6,who:"dog",cards:[{t:"say",pose:"wave",text:"Chào em, Cún Đốm đây! Có lúc em cần viết <b>thư</b> cho bà, gửi <b>giấy mời</b> bố mẹ, viết <b>thông báo</b> cho lớp hay viết <b>đơn</b>. Mỗi loại có một <b>khuôn</b> riêng. Nhớ khuôn là viết được ngay!"},{t:"steps",title:"Bức thư gồm 3 phần",items:[{text:"<b>Đầu thư</b>: địa điểm, ngày tháng năm; lời xưng hô (Bà kính yêu!)."},{text:"<b>Phần chính</b>: hỏi thăm người nhận, kể tin tức của mình."},{text:"<b>Cuối thư</b>: lời chúc, lời hứa; chữ kí và tên."}]},{t:"pic",svg:h("",'<div style="text-align:right">Hải Phòng, ngày 10 tháng 3 năm 2026</div>Bà kính yêu!<br>Dạo này bà có khoẻ không ạ? Chân bà còn đau không? Cháu ở nhà vẫn ngoan. Tuần rồi, cháu được cô khen vì viết chữ đẹp. Hè này, cháu sẽ về quê thăm bà.<br>Cháu chúc bà luôn mạnh khoẻ.<div style="text-align:right">Cháu của bà<br>Mai</div>'),cap:"Một bức thư ngắn có đủ ba phần."},{t:"try",q:{text:'Dòng "Bà kính yêu!" thuộc phần nào của bức thư?',opts:["Đầu thư","Phần chính","Cuối thư"],ans:0,hint:"Lời xưng hô, gọi người nhận, đứng ở đâu trong thư?",why:'Lời xưng hô "Bà kính yêu!" nằm ở <b>đầu thư</b>, ngay sau dòng ngày tháng.'}},{t:"say",text:"<b>Giấy mời</b> và <b>thông báo</b> phải ghi rõ: <b>việc gì, lúc nào, ở đâu</b>. Thiếu một ý là người đọc không biết đường mà đến!"},{t:"pic",svg:h("GIẤY MỜI",'Kính gửi: Bố mẹ bạn Lê Minh Anh<br>Lớp 3B trân trọng kính mời bố mẹ đến dự buổi biểu diễn văn nghệ chào mừng ngày Nhà giáo Việt Nam 20 – 11.<br>Thời gian: 8 giờ sáng thứ bảy, ngày 14 tháng 11 năm 2026.<br>Địa điểm: Hội trường Trường Tiểu học Hoà Bình.<br>Rất mong bố mẹ đến dự.<div style="text-align:right">Thay mặt lớp<br>Lớp trưởng: Trần Gia Bảo</div>'),cap:"Giấy mời ghi rõ <b>mời ai, dự việc gì, lúc nào, ở đâu</b>, ai mời."},{t:"try",q:{text:"Giấy mời trên mời bố mẹ đến dự việc gì?",opts:["Họp phụ huynh","Biểu diễn văn nghệ","Lễ khai giảng năm học mới","Hội chợ"],ans:1,hint:'Đọc dòng "trân trọng kính mời…".',why:"Giấy mời ghi: đến dự <b>buổi biểu diễn văn nghệ</b> chào mừng ngày 20 – 11."}},{t:"try",q:{text:"Nếu giấy mời <b>thiếu dòng địa điểm</b>, người được mời sẽ không biết điều gì?",opts:["Dự việc gì","Đến lúc nào","Đến ở đâu","Ai mời"],ans:2,hint:"Địa điểm trả lời câu hỏi nào: Lúc nào? Ở đâu?",why:"Địa điểm cho biết <b>đến ở đâu</b>. Thiếu dòng này, bố mẹ không biết đi đến chỗ nào."}},{t:"say",text:"<b>Đơn</b> là giấy viết gửi người có trách nhiệm để <b>xin</b> một điều gì: xin nghỉ học, xin vào Đội, xin cấp thẻ thư viện… Đơn có khuôn chặt chẽ nhất."},{t:"steps",title:"Các phần của lá đơn",items:[{text:"1. Quốc hiệu, tiêu ngữ: CỘNG HOÀ XÃ HỘI CHỦ NGHĨA VIỆT NAM – Độc lập – Tự do – Hạnh phúc."},{text:"2. Địa điểm, ngày tháng năm viết đơn."},{text:"3. Tên đơn: ĐƠN XIN …"},{text:"4. Kính gửi: người nhận đơn (cô giáo chủ nhiệm, cô thủ thư…)."},{text:"5. Người viết tự giới thiệu, nêu lí do, điều mong muốn và lời hứa."},{text:"6. Lời cảm ơn; chữ kí và họ tên người viết."}]},{t:"try",q:{text:"Xếp các phần của lá đơn theo đúng thứ tự từ trên xuống.",...c(["Quốc hiệu, tiêu ngữ","Tên đơn","Kính gửi","Lí do, mong muốn","Chữ kí, họ tên"]),ph:"Chạm các phần theo thứ tự từ trên xuống",hint:"Quốc hiệu luôn ở trên cùng; chữ kí ở cuối cùng.",why:"Quốc hiệu, tiêu ngữ → tên đơn → kính gửi → lí do, mong muốn → chữ kí, họ tên."}},{t:"tip",text:"• Thư: <b>đầu thư</b> (ngày tháng, xưng hô) → <b>phần chính</b> → <b>cuối thư</b> (lời chúc, chữ kí).<br>• Giấy mời, thông báo: ghi rõ <b>việc gì, lúc nào, ở đâu</b>.<br>• Đơn: quốc hiệu → tên đơn → kính gửi → lí do, mong muốn → chữ kí."}],practice:[{id:"tv3.viet-vanban.1",text:"Bức thư thường bắt đầu bằng dòng nào?",opts:["Lời chúc sức khoẻ","Địa điểm, ngày tháng năm","Chữ kí và tên người viết","Lời hứa"],ans:1,why:"Dòng đầu tiên của thư ghi <b>địa điểm, ngày tháng năm</b>, rồi mới đến lời xưng hô."},{id:"tv3.viet-vanban.2",text:"Thông báo của lớp về buổi lao động cần ghi rõ những gì?",opts:["Chỉ cần ngày giờ","Chỉ cần tên lớp","Lời chúc và chữ kí của cô","Việc gì, lúc nào, ở đâu"],ans:3,why:"Thông báo phải cho biết <b>việc gì, lúc nào, ở đâu</b> để mọi người làm đúng."},{id:"tv3.viet-vanban.3",text:"Câu nào hợp làm lời <b>cuối thư</b> gửi ông?",opts:["Hà Nội, ngày 5 tháng 4 năm 2026","Ông kính yêu!","Cháu chúc ông mạnh khoẻ, sống lâu.","Dạo này ông bà ở quê có khoẻ không ạ?"],ans:2,why:'Cuối thư là <b>lời chúc</b>, lời hứa. Ngày tháng và "Ông kính yêu!" ở đầu thư; câu hỏi thăm ở phần chính.'},{id:"tv3.viet-vanban.4",text:'Em viết đơn xin nghỉ học một ngày vì bị ốm. Dòng "Kính gửi" nên ghi ai?',opts:["Cô giáo chủ nhiệm","Bạn cùng bàn","Bác bảo vệ của trường","Em trai"],ans:0,why:"Đơn gửi <b>người có trách nhiệm</b> giải quyết việc đó. Xin nghỉ học thì gửi cô giáo chủ nhiệm."},{id:"tv3.viet-vanban.5",text:"Xếp các phần của giấy mời theo đúng thứ tự từ trên xuống.",...c(["GIẤY MỜI","Kính gửi …","Mời dự việc gì","Thời gian, địa điểm","Người mời kí tên"]),ph:"Chạm các phần theo thứ tự từ trên xuống",why:"Tên giấy mời → kính gửi ai → mời dự việc gì → thời gian, địa điểm → người mời kí tên."}]}]}])})();
